import{_ as a,o as r,c as d,ag as o}from"./chunks/framework.D2veAa-g.js";const g=JSON.parse('{"title":"操作系统-嵌入式与实时系统","description":"","frontmatter":{"title":"操作系统-嵌入式与实时系统"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/嵌入式与实时系统.md","filePath":"综合知识/系统基础/操作系统/嵌入式与实时系统.md","lastUpdated":null}'),n={name:"综合知识/系统基础/操作系统/嵌入式与实时系统.md"};function s(e,t,l,i,h,p){return r(),d("div",null,[...t[0]||(t[0]=[o(`<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] RTOS 任务调度器</li><li>[ ] 微内核操作系统结构</li><li>[ ] 中断处理机制</li><li>[ ] 紧耦合多机系统与 SMP</li><li>[ ] 多核 CPU 调度算法</li><li>[ ] 流水线执行时间计算</li><li>[ ] 嵌入式操作系统特点</li><li>[ ] 分层架构脆弱性</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="rtos-任务调度器" tabindex="-1">RTOS 任务调度器 <a class="header-anchor" href="#rtos-任务调度器" aria-label="Permalink to &quot;RTOS 任务调度器&quot;">​</a></h3><blockquote><p>🎯 一句话结论：大多数 RTOS 调度算法都是<strong>抢占方式（可剥夺方式）</strong>，目标是<strong>实时性</strong>而非公平性。</p></blockquote><table tabindex="0"><thead><tr><th>选项</th><th>正误</th><th>解析</th></tr></thead><tbody><tr><td>公平性是最重要的调度目标</td><td>❌</td><td>RTOS 首要目标是<strong>实时性</strong>，确保任务在规定时间内完成</td></tr><tr><td>大多采用抢占方式</td><td>✅</td><td>可剥夺方式，高优先级任务可抢占 CPU</td></tr><tr><td>都采用时间片轮转</td><td>❌</td><td>通常采用<strong>优先级调度</strong>，而非时间片轮转</td></tr><tr><td>只采用静态优先级</td><td>❌</td><td>常用<strong>动态优先级</strong>调度算法</td></tr></tbody></table><h3 id="微内核操作系统结构" tabindex="-1">微内核操作系统结构 <a class="header-anchor" href="#微内核操作系统结构" aria-label="Permalink to &quot;微内核操作系统结构&quot;">​</a></h3><blockquote><p>🎯 一句话结论：微内核中，<strong>内核服务运行在用户态</strong>，<strong>客户端程序也运行在用户态</strong>，内核本身很小，大部分 OS 功能以服务进程形式存在。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────┐</span></span>
<span class="line"><span>│  客户端程序（用户态）      │</span></span>
<span class="line"><span>├─────────────────────────┤</span></span>
<span class="line"><span>│  内核服务（用户态）②       │  ← 传统 OS 中本在核心态的功能</span></span>
<span class="line"><span>├─────────────────────────┤</span></span>
<span class="line"><span>│  微内核（核心态）①         │  ← 极小内核，仅最基础功能</span></span>
<span class="line"><span>└─────────────────────────┘</span></span></code></pre></div><ul><li>① 工作在<strong>用户态</strong>（内核服务），② 工作在<strong>用户态</strong>（客户端）</li><li>优点：提高系统<strong>灵活性、可扩充性</strong>，增强了可靠性</li><li>缺点：用户态和核心态切换频繁，<strong>性能有所降低</strong></li></ul><h3 id="中断处理机制" tabindex="-1">中断处理机制 <a class="header-anchor" href="#中断处理机制" aria-label="Permalink to &quot;中断处理机制&quot;">​</a></h3><blockquote><p>🎯 一句话结论：嵌入式系统中采用中断方式的目的是<strong>提高 CPU 效率</strong>（不用轮询等待），CPU 断点信息保存到<strong>栈</strong>中。</p></blockquote><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>中断目的</td><td>让 CPU 不用轮询等待外设，提高效率</td></tr><tr><td>断点保存位置</td><td><strong>栈</strong>（不是通用寄存器、堆或 I/O 接口）</td></tr><tr><td>中断过程</td><td>外设发中断信号 → CPU 响应 → 保存断点到栈 → 执行中断处理程序 → 恢复断点继续执行</td></tr><tr><td>缺页中断</td><td>属于<strong>内部中断</strong>（程序性中断），处理过程称为<strong>页面置换</strong></td></tr></tbody></table><h3 id="紧耦合多机系统与-smp" tabindex="-1">紧耦合多机系统与 SMP <a class="header-anchor" href="#紧耦合多机系统与-smp" aria-label="Permalink to &quot;紧耦合多机系统与 SMP&quot;">​</a></h3><blockquote><p>🎯 一句话结论：紧耦合多机系统通过<strong>共享内存</strong>实现通信，**SMP（对称多处理器）**属于紧耦合系统。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>通信方式</th><th>特点</th></tr></thead><tbody><tr><td><strong>紧耦合</strong></td><td>共享内存</td><td>多 CPU 共享同一主存，通过共享内存交换数据</td></tr><tr><td><strong>松耦合</strong></td><td>消息传递/网络</td><td>各系统独立内存，通过通信线路连接</td></tr></tbody></table><p><strong>SMP</strong>：多个处理器对称访问共享内存，无主从之分，由单一操作系统管理。</p><h3 id="多核-cpu-调度算法" tabindex="-1">多核 CPU 调度算法 <a class="header-anchor" href="#多核-cpu-调度算法" aria-label="Permalink to &quot;多核 CPU 调度算法&quot;">​</a></h3><blockquote><p>🎯 一句话结论：全局队列调度 CPU 利用率高但缓存利用率低；局部队列调度缓存利用率高但 <strong>CPU 利用率低</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>调度方式</th><th>原理</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td><strong>全局队列</strong></td><td>所有 CPU 共享一个任务等待队列</td><td>CPU 利用率高</td><td>缓存利用率低</td></tr><tr><td><strong>局部队列</strong></td><td>每个 CPU 有独立任务队列</td><td>缓存利用率高</td><td><strong>CPU 利用率低</strong></td></tr></tbody></table><p>⚠️ 记忆：全局→全局竞争→CPU 不闲着→利用率高；局部→各管各的→可能有 CPU 闲着→利用率低。</p><h3 id="流水线执行时间计算" tabindex="-1">流水线执行时间计算 <a class="header-anchor" href="#流水线执行时间计算" aria-label="Permalink to &quot;流水线执行时间计算&quot;">​</a></h3><blockquote><p>🎯 一句话结论：流水线时间 = <strong>1 条指令顺序执行时间 +（总指令数 - 1）× 最长段执行时间</strong>。<br> 简写作：T = ΣΔt + (n - 1) × Δt_max</p></blockquote><p><strong>计算步骤</strong>：</p><ol><li>确定最长功能段的执行时间 Δt_max（瓶颈段）</li><li>计算单条指令顺序执行总时间 ΣΔt（各段时间之和）</li><li>代入公式</li></ol><p><strong>实例</strong>（Q62）：5 段流水线，各段时间 2ns、3ns、1ns、4ns、2ns，100 条指令。</p><ul><li>ΣΔt = 2 + 3 + 1 + 4 + 2 = 12ns</li><li>Δt_max = 4ns</li><li>T = 12 + (100 - 1) × 4 = 12 + 396 = <strong>408ns</strong></li></ul><h3 id="嵌入式操作系统特点" tabindex="-1">嵌入式操作系统特点 <a class="header-anchor" href="#嵌入式操作系统特点" aria-label="Permalink to &quot;嵌入式操作系统特点&quot;">​</a></h3><blockquote><p>🎯 一句话结论：嵌入式 OS 的特点是<strong>微型化、可定制、实时性、可靠性、易移植性</strong>。不需要图形界面友好。</p></blockquote><table tabindex="0"><thead><tr><th>特点</th><th>说明</th></tr></thead><tbody><tr><td>微型化</td><td>内核精小，占用资源少</td></tr><tr><td>可定制性</td><td>按需求裁剪功能模块</td></tr><tr><td>实时性</td><td>在规定时间内响应事件</td></tr><tr><td>可靠性</td><td>长期稳定运行</td></tr><tr><td>易移植性</td><td>采用 HAL（硬件抽象层）和 BSP（板级支持包）设计</td></tr><tr><td>❌ 图形界面友好</td><td>非必要特征，很多嵌入式系统无 GUI</td></tr></tbody></table><h3 id="分层架构脆弱性" tabindex="-1">分层架构脆弱性 <a class="header-anchor" href="#分层架构脆弱性" aria-label="Permalink to &quot;分层架构脆弱性&quot;">​</a></h3><blockquote><p>🎯 一句话结论：分层架构的两个脆弱性 — <strong>底层错误导致整个系统无法正常运行</strong> + <strong>层间通信机制造成性能下降</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>脆弱性</th><th>原因</th></tr></thead><tbody><tr><td>底层错误导致整个系统崩溃</td><td>上层依赖下层，底层故障向上传播</td></tr><tr><td>层间通信造成性能下降</td><td>每层穿越都有开销</td></tr></tbody></table><p>⚠️ 注意：不是&quot;上层错误导致系统崩溃&quot;（上层错误通常只影响自身），也不是&quot;功能引用导致功能失效&quot;（分层架构设计要求上层调用下层，不应反向引用）。</p>`,34)])])}const c=a(n,[["render",s]]);export{g as __pageData,c as default};
